files.game.js:
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 400,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 1000 },
      debug: false
    }
  },
  scene: { preload, create, update }
};

let player, ground, obstacles, coins, jumpKey;
let score = 0, distance = 0, gameSpeed = 300;
let scoreText, distanceText, gameOver = false;
let obstacleTimer = 0, coinTimer = 0;

const game = new Phaser.Game(config);

function preload() {
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Player (blue square)
  graphics.fillStyle(0x0088ff, 1);
  graphics.fillRect(0, 0, 32, 32);
  graphics.generateTexture('player', 32, 32);
  graphics.clear();

  // Ground (green)
  graphics.fillStyle(0x00aa00, 1);
  graphics.fillRect(0, 0, 800, 50);
  graphics.generateTexture('ground', 800, 50);
  graphics.clear();

  // Obstacle (red)
  graphics.fillStyle(0xff0000, 1);
  graphics.fillRect(0, 0, 30, 40);
  graphics.generateTexture('obstacle', 30, 40);
  graphics.clear();

  // Coin (yellow)
  graphics.fillStyle(0xffd700, 1);
  graphics.fillCircle(12, 12, 12);
  graphics.generateTexture('coin', 24, 24);
}

function create() {
  // Ground
  ground = this.physics.add.staticGroup();
  ground.create(400, 375, 'ground');

  // Player
  player = this.physics.add.sprite(100, 300, 'player');
  player.setCollideWorldBounds(true);

  // Groups
  obstacles = this.physics.add.group();
  coins = this.physics.add.group();

  // Collisions
  this.physics.add.collider(player, ground);
  this.physics.add.collider(obstacles, ground);
  this.physics.add.collider(coins, ground);
  this.physics.add.overlap(player, obstacles, hitObstacle, null, this);
  this.physics.add.overlap(player, coins, collectCoin, null, this);

  // Input
  jumpKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

  // UI
  scoreText = this.add.text(16, 16, 'Score: 0', {
    fontSize: '20px',
    fill: '#000'
  });
  distanceText = this.add.text(16, 40, 'Distance: 0m', {
    fontSize: '20px',
    fill: '#000'
  });
}

function update(time) {
  if (gameOver) return;

  // Jump
  if (Phaser.Input.Keyboard.JustDown(jumpKey) && player.body.touching.down) {
    player.setVelocityY(-500);
  }

  // Update distance
  distance += 0.1;
  distanceText.setText('Distance: ' + Math.floor(distance) + 'm');

  // Increase speed
  if (Math.floor(distance) % 50 === 0 && Math.floor(distance) > 0) {
    gameSpeed += 10;
  }

  // Spawn obstacles
  if (time > obstacleTimer) {
    const obstacle = obstacles.create(850, 330, 'obstacle');
    obstacle.setVelocityX(-gameSpeed);
    obstacleTimer = time + Phaser.Math.Between(1500, 3000);
  }

  // Spawn coins
  if (time > coinTimer) {
    const yPos = Phaser.Math.Between(200, 320);
    const coin = coins.create(850, yPos, 'coin');
    coin.setVelocityX(-gameSpeed);
    coinTimer = time + Phaser.Math.Between(800, 1500);
  }

  // Clean up off-screen objects
  obstacles.children.each(obstacle => {
    if (obstacle.x < -50) obstacle.destroy();
  });

  coins.children.each(coin => {
    if (coin.x < -50) coin.destroy();
  });
}

function collectCoin(player, coin) {
  coin.destroy();
  score += 5;
  scoreText.setText('Score: ' + score);
}

function hitObstacle() {
  gameOver = true;
  this.physics.pause();
  player.setTint(0xff0000);

  this.add.text(400, 200, 'GAME OVER', {
    fontSize: '48px',
    fill: '#ff0000'
  }).setOrigin(0.5);

  this.add.text(400, 250, 'Final Score: ' + score, {
    fontSize: '24px',
    fill: '#000'
  }).setOrigin(0.5);
}
